// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout } from '@stdlib/types/blas';

/**
* Interface describing `dcomputeInertia`.
*/
interface Routine {
	/**
	* Compute inertia between double-precision floating-point centroids and data points.
	*
	* @param order - storage layout
	* @param M - number of data points
	* @param N - number of features
	* @param k - number of centroids
	* @param metric - distance metric
	* @param X - input data matrix
	* @param LDX - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
	* @param C - centroid matrix
	* @param LDC - stride of the first dimension of `C` (a.k.a., leading dimension of the matrix `C`)
	* @param labels - labels array containing cluster index of each data point.
	* @param sl - stride length of labels.
	* @returns inertia
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var X = new Float64Array( [ 1.0, 1.0, 5.0, 5.0, 1.5, 1.5 ] );
	* var C = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
	* var labels = new Int32Array( [ 0, 1, 0 ] );
	*
	* var inertia = dcomputeInertia( 'row-major', 3, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 );
	* // returns 0.5
	*/
	( order: Layout, M: number, N: number, k: number, metric: string, X: Float64Array, LDX: number, C: Float64Array, LDC: number, labels: Int32Array, sl: number ): number;

	/**
	* Compute inertia between double-precision floating-point centroids and data points using alternative indexing semantics.
	*
	* @param M - number of data points
	* @param N - number of features
	* @param k - number of centroids
	* @param metric - distance metric
	* @param X - input data matrix
	* @param sx1 - stride of the first dimension of `X`
	* @param sx2 - stride of the second dimension of `X`
	* @param ox - starting index for `X`
	* @param C - centroid matrix
	* @param sc1 - stride of the first dimension of `C`
	* @param sc2 - stride of the second dimension of `C`
	* @param oc - starting index for `C`
	* @param labels - labels array containing cluster index of each data point.
	* @param sl - stride length of labels.
	* @param ol - starting index for `labels`
	* @returns inertia
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var X = new Float64Array( [ 1.0, 1.0, 5.0, 5.0, 1.5, 1.5 ] );
	* var C = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
	* var labels = new Int32Array( [ 0, 1, 0 ] );
	*
	* var inertia = dcomputeInertia.ndarray( 3, 2, 2, 'sqeuclidean', X, 2, 1, 0, C, 2, 1, 0, labels, 1, 0 );
	* // returns 0.5
	*/
	ndarray( M: number, N: number, k: number, metric: string, X: Float64Array, sx1: number, sx2: number, ox: number, C: Float64Array, sc1: number, sc2: number, oc: number, labels: Int32Array, sl: number, ol: number ): number;
}

/**
* Compute inertia between double-precision floating-point centroids and data points.
*
* @param order - storage layout
* @param M - number of data points
* @param N - number of features
* @param k - number of centroids
* @param metric - distance metric
* @param X - input data matrix
* @param LDX - stride of the first dimension of `X` (a.k.a., leading dimension of the matrix `X`)
* @param C - centroid matrix
* @param LDC - stride of the first dimension of `C` (a.k.a., leading dimension of the matrix `C`)
* @param labels - labels array containing cluster index of each data point.
* @param sl - stride length of labels.
* @returns inertia
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var X = new Float64Array( [ 1.0, 1.0, 5.0, 5.0, 1.5, 1.5 ] );
* var C = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
* var labels = new Int32Array( [ 0, 1, 0 ] );
*
* var inertia = dcomputeInertia( 'row-major', 3, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 );
* // returns 0.5
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var X = new Float64Array( [ 1.0, 1.0, 5.0, 5.0, 1.5, 1.5 ] );
* var C = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
* var labels = new Int32Array( [ 0, 1, 0 ] );
*
* var inertia = dcomputeInertia.ndarray( 3, 2, 2, 'sqeuclidean', X, 2, 1, 0, C, 2, 1, 0, labels, 1, 0 );
* // returns 0.5
*/
declare var dcomputeInertia: Routine;


// EXPORTS //

export = dcomputeInertia;
